struct RequestContext { std::string id; User user; };

thread_local RequestContext current;             // one instance per thread, built lazily

RequestContext& ctx() { return current; }        // looks like a global, costs like a local

void handle(const Request& r) {
    ctx().id = r.id();                           // no mutex, no parameter, no key
}                                                // destroyed at thread exit

