#include <boost/thread/tss.hpp>

static boost::thread_specific_ptr<Ctx> ctx_ptr;   // address of the object is the key

Ctx& ctx() {
    Ctx* p = ctx_ptr.get();                        // NULL on first use in a thread
    if (!p) { p = new Ctx(); ctx_ptr.reset(p); }
    return *p;                                     // deleted when the thread exits
}

#include "ace/TSS_T.h"

typedef ACE_TSS<RequestContext> TSS_Context;
static TSS_Context ctx;                 // one proxy, one RequestContext per thread

void handle() {
    ctx->request_id = next_id();        // operator->() hides key and collection
}                                       // all threads' copies die with the ACE_TSS object
